#include "pilot_slot_cursor.hpp"
#include <cstdio>
int main(){try{using namespace tao::data;std::vector<std::vector<Token>> docs{{{BOS,false},{USER,false},{97,false},{TURN_END,false},{ASSISTANT,false},{261,true},{TURN_END,true}},{{BOS,false},{ASSISTANT,false},{262,true},{263,true},{TURN_END,true}}};PilotCursor c(docs,4,false);size_t positions=0,resets=0;for(int epoch=0;epoch<2;++epoch){for(;;){bool any=false;for(size_t k=0;k<4;++k){Work w;if(!c.take(k,2,w))continue;any=true;resets+=w.reset;positions+=w.end-w.begin;if(w.reset&&w.begin!=1)throw std::runtime_error("reset position");}if(!any)break;}bool exhausted=c.next==c.docs.size();for(auto&s:c.slots)if(s.doc!=std::numeric_limits<size_t>::max()&&s.target<c.docs[s.doc].size())exhausted=false;if(!exhausted)throw std::runtime_error("not exhausted");c.next=0;for(auto&s:c.slots)s=Cursor{};}if(positions!=20||resets!=4)throw std::runtime_error("coverage");printf("PASS two epochs positions=%zu document_resets=%zu unused_slots_safe=1\n",positions,resets);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
